package com.e02.rootconsole;
public final class TestAdbControl {
 public static void main(String[] args){for(String bad:new String[]{"1.2.3.4;reboot","1.2.3.256","127.0.0.1","0.0.0.0","224.0.0.1","01.2.3.4","1.2.3","$(id)",null}){boolean rejected=false;try{AdbControl.ipv4(bad);}catch(IllegalArgumentException e){rejected=true;}if(!rejected)throw new AssertionError("Invalid address accepted");}String on=AdbControl.wireless(true,"192.0.2.10","192.0.2.20"),off=AdbControl.wireless(false,"192.0.2.10","192.0.2.20");if(on.contains("iptables -F INPUT")||off.contains("stop adbd")||off.contains("setprop"))throw new AssertionError("Wireless switch affects unrelated firewall/USB");if(!on.contains("-s 192.0.2.20 -d 192.0.2.10")||!on.contains("E02_WIFI_ADB -j DROP"))throw new AssertionError("Missing restricted peer/default block");if(!AdbControl.wired(false).contains("persist.vendor.setusbmode false"))throw new AssertionError("USB restore missing");if(!AdbControl.status("192.0.2.10", "").contains("WIRELESS=unknown"))throw new AssertionError("Blank peer must leave wireless status unknown");System.out.println("ADB control: validation and scope PASS");}
}
